mapper.select:
select *
from cr_eval_template


        and category_code = #{evalTemplateListQuery.categoryCode}


        and create_user_id = #{userId}



        and name like #{pattern}

select *
from cr_eval_template


        and category_code = #{evalTemplateListQuery.categoryCode}



        and ( create_user_id = #{userId} or 
        	resource_id in 
        		(
        			select te.resource_id from cr_eval_template te, cr_eval_task ta, cr_eval_task_step st 
        			where te.resource_id = ta.template_id and ta.resource_id = st.task_id and st.user_ids like #{userIdPattern}
        		) 
        	)



        and name like #{pattern}

select case
when exists(select 1
from cr_eval_template
where `name` = #{templateName}
and create_user_id = #{createUserId}

    and resource_id != #{templateId}
)
then 1
else 0
end
as result;
